import React, { useEffect, useRef, useState } from 'react';
import { createRoot } from 'react-dom/client';
import { LayoutDashboard, Package, Files, ReceiptText, Ship, Wallet, Users, Search, Plus, ArrowUpRight, ArrowRight, Download, RefreshCw, LogOut, X, ChevronRight, FileText, Check, AlertCircle, Anchor, Upload, Eye, Trash2, Leaf, LockKeyhole } from 'lucide-react';
import { supabase, configured, exampleMode, number, money, date, today, errorMessage, loadData, rpc, save, downloadCSV } from './lib';
import { demoData } from './demo';
import './style.css';

const NAV=[['forecast','Forecast',LayoutDashboard],['productos','Productos',Package],['proformas','Proformas',Files],['facturas','Facturas',ReceiptText],['seguimiento','Seguimiento',Ship],['pagos','Pagos',Wallet],['usuarios','Usuarios',Users]];
const TITLES={forecast:['Todo tu pedido, en perspectiva.','Consulta lo pedido, lo facturado y lo que falta recibir.'],productos:['Catálogo de productos','Una referencia compartida para todos tus documentos.'],proformas:['Proformas','El pedido original y su avance, sin perder el detalle.'],facturas:['Facturas comerciales','Lo que el proveedor factura, tal como lo emite.'],seguimiento:['Seguimiento de llegadas','Fechas estimadas, fechas reales y recepción física.'],pagos:['Control de pagos','Anticipos y saldos de cada factura, por separado.'],usuarios:['Personas y accesos','Un espacio compartido, con permisos para cada función.']};
const blankLine=()=>({key:crypto.randomUUID(),producto_id:'',cantidad:'',unidad:'CAJA',packing:'',precio_unitario:'',referencia_proforma_documento:'',asignaciones:[]});
const sum=(rows,key)=>rows.reduce((n,r)=>n+Number(r[key]||0),0);
const byId=(rows,id)=>rows.find(r=>r.id===id);

function Badge({children,tone=''}) { return <span className={'badge '+tone}>{children}</span>; }
function Field({label,children,hint}) { return <label className="field"><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>; }
function Empty({title='Todavía no hay registros',text='Los documentos que registres aparecerán aquí.',action}) { return <div className="empty"><div className="empty-icon"><Files size={27}/></div><h3>{title}</h3><p>{text}</p>{action}</div>; }
function Button({children,icon:Icon,secondary=false,...props}) { return <button className={secondary?'button secondary':'button'} {...props}>{Icon&&<Icon size={16}/>}<span>{children}</span></button>; }
function Modal({title,children,onClose,wide=false}) {
  const ref=useRef();
  useEffect(()=>{ref.current.showModal();},[]);
  return <dialog ref={ref} onCancel={e=>{e.preventDefault();onClose();}} className={wide?'modal wide':'modal'} aria-labelledby="modal-title"><div className="modal-head"><div><span className="eyebrow">CONTROL DE IMPORTACIONES</span><h2 id="modal-title">{title}</h2></div><button className="icon-button" aria-label="Cerrar" onClick={onClose}><X size={20}/></button></div>{children}</dialog>;
}
function App() {
  const [session,setSession]=useState(null), [ready,setReady]=useState(exampleMode), [profile,setProfile]=useState(null), [data,setData]=useState(exampleMode?demoData():null);
  const [page,setPage]=useState('forecast'),[modal,setModal]=useState(null),[busy,setBusy]=useState(false),[loading,setLoading]=useState(false),[error,setError]=useState(''),[notice,setNotice]=useState('');
  const [passwordMode,setPasswordMode]=useState(new URLSearchParams(location.search).get('acceso')==='1' || /type=(invite|recovery)/.test(location.hash));
  const [query,setQuery]=useState('');
  useEffect(()=>{
    if(exampleMode) {setProfile(demoData().perfiles[0]);return;}
    if(!supabase) {setReady(true);return;}
    let active=true;
    supabase.auth.getSession().then(({data,error})=>{if(active){setSession(data.session);setReady(true);if(error)setError(errorMessage(error));}});
    const {data:{subscription}}=supabase.auth.onAuthStateChange((event,s)=>{
      if(!active)return;setSession(s);setReady(true);
      if(event==='PASSWORD_RECOVERY')setPasswordMode(true);
      if(event==='SIGNED_OUT'){setData(null);setProfile(null);setModal(null);}
    });
    return()=>{active=false;subscription.unsubscribe();};
  },[]);
  useEffect(()=>{
    if(exampleMode||!session)return;
    let active=true;
    setLoading(true);setProfile(null);setData(null);setError('');
    (async()=>{
      try {
        const {data:p,error}=await supabase.from('perfiles').select('*').eq('id',session.user.id).maybeSingle();
        if(error)throw error;
        if(!active)return;setProfile(p);
        if(p?.activo){const d=await loadData();if(active)setData(d);}
      } catch(e){if(active)setError(errorMessage(e));}
      finally {if(active)setLoading(false);}
    })();return()=>{active=false;};
  },[session?.user.id]);
  useEffect(()=>{if(!notice)return;const t=setTimeout(()=>setNotice(''),7000);return()=>clearTimeout(t);},[notice]);
  const admin=profile?.rol==='administracion';
  async function refresh() {if(exampleMode)return;setLoading(true);try{setData(await loadData());setError('');}catch(e){setError(errorMessage(e));}finally{setLoading(false);}}
  async function action(fn,message='Registro guardado') {
    if(exampleMode){setError('Esta vista utiliza datos ficticios y no guarda cambios.');return false;}
    if(busy)return false;setBusy(true);setError('');
    try {await fn();setModal(null);setNotice(message);await refresh();return true;}catch(e){setError(errorMessage(e));return false;}finally{setBusy(false);}
  }
  async function signout(){if(exampleMode){location.href='/';return;}const {error}=await supabase.auth.signOut();if(error)setError(errorMessage(error));}
  function open(type,value){setError('');setModal({type,value});}
  if(!ready)return <div className="splash"><Leaf/> Cargando tu espacio…</div>;
  if(!session&&!exampleMode || passwordMode&&!exampleMode) return <Auth session={session} passwordMode={passwordMode} onDone={()=>{setPasswordMode(false);history.replaceState(null,'',location.pathname);}}/>;
  if(loading&&!data || !profile) return <div className="access-wrap"><Brand/>{loading?<p>Preparando tu espacio…</p>:<><h2>{error?'No pudimos cargar tu acceso':'Tu acceso está pendiente'}</h2><p>{error||'Tu cuenta necesita un perfil activo. La persona responsable del proyecto puede habilitarlo.'}</p><Button onClick={()=>location.reload()} secondary>Volver a intentar</Button><button className="text-button" onClick={signout}>Cerrar sesión</button></>}</div>;
  if(!data)return <div className="access-wrap"><h2>No pudimos cargar los registros</h2><p role="alert">{error}</p><Button onClick={refresh}>Volver a intentar</Button><button onClick={signout}>Cerrar sesión</button></div>;
  return <div className="app-shell">
    <aside className="sidebar"><Brand/><div className="workspace-label">ESPACIO DE TRABAJO</div><nav aria-label="Navegación principal">{NAV.map(([id,label,Icon])=><button key={id} aria-label={label} className={page===id?'nav-item active':'nav-item'} onClick={()=>{setPage(id);setQuery('');}} aria-current={page===id?'page':undefined}><Icon size={19}/><span>{label}</span>{page===id&&<span className="nav-dot"/>}</button>)}</nav><div className="sidebar-bottom"><div className="small-label">TODO EN UN MISMO LUGAR</div><p>Del pedido a la llegada.<br/>Cada documento cuenta.</p><div className="user"><div className="avatar">{profile.nombre.slice(0,2).toUpperCase()}</div><div><strong>{profile.nombre}</strong><small>{admin?'Administración':'Solo consulta'}</small></div><button aria-label="Cerrar sesión" onClick={signout} className="icon-button"><LogOut size={16}/></button></div></div></aside>
    <div className="main-wrap"><header className="topbar"><div className="breadcrumb">Importaciones <ChevronRight size={14}/><strong>{NAV.find(n=>n[0]===page)[1]}</strong></div><div className="topbar-right"><span className="connection"><i/>{exampleMode?'Datos ficticios':'Espacio conectado'}</span><span className="today">{date(today())}</span></div></header>
    <main>{exampleMode&&<div className="demo-banner"><Eye size={16}/><span>Vista de ejemplo · datos ficticios · los cambios no se guardan</span><a href="/">Ir al acceso real <ArrowRight size={14}/></a></div>}
      <div className="page-heading"><div><div className="eyebrow">SANAT PHARMA / {page==='forecast'?'VISIBILIDAD Y CONTROL':'CONTROL DE IMPORTACIONES'}</div><h1>{TITLES[page][0]}</h1><p>{TITLES[page][1]}</p></div><button className="refresh-button" onClick={refresh} disabled={loading||exampleMode} aria-label="Actualizar datos"><RefreshCw size={17} className={loading?'spin':''}/></button></div>
      {error&&<div className="message error" role="alert"><AlertCircle size={18}/>{error}<button className="icon-button" aria-label="Cerrar aviso" onClick={()=>setError('')}><X size={16}/></button></div>}
      {notice&&<div className="message success" role="status"><Check size={18}/>{notice}</div>}
      {page==='forecast'&&<Forecast data={data} query={query} setQuery={setQuery}/>}
      {page==='productos'&&<Products data={data} admin={admin} query={query} setQuery={setQuery} open={open}/>}
      {(page==='proformas'||page==='facturas')&&<Documents kind={page==='proformas'?'proforma':'factura'} data={data} admin={admin} open={open}/>}
      {page==='seguimiento'&&<Tracking data={data} admin={admin} open={open}/>}
      {page==='pagos'&&<Payments data={data} admin={admin} open={open}/>}
      {page==='usuarios'&&<div className="panel"><div className="panel-title"><div><h2>Accesos del equipo</h2><p>La administración de cuentas se realiza desde el proyecto.</p></div><Badge>{data.perfiles.length} personas</Badge></div><div className="team-grid">{data.perfiles.map(p=><div className="person" key={p.id}><div className="avatar">{p.nombre.slice(0,2).toUpperCase()}</div><div><strong>{p.nombre}</strong><p>{p.rol==='administracion'?'Registro y seguimiento':'Consulta del control'}</p><Badge tone={p.activo?'green':'amber'}>{p.activo?'Acceso activo':'Desactivado'}</Badge></div></div>)}</div><p className="footnote">Los roles protegen los datos también en la base. Cada persona utiliza su propia cuenta.</p></div>}
      <footer>Sanat Pharma <span>Control de importaciones · {exampleMode?'Ejemplo visual':'Información del equipo'}</span></footer>
    </main></div>
    {modal&&<Modal title={modalTitle(modal)} onClose={()=>!busy&&setModal(null)} wide={['document','detail','receipt'].includes(modal.type)}>
      {error&&<div className="message error" role="alert">{error}</div>}
      {modal.type==='product'&&<ProductForm value={modal.value} data={data} busy={busy} action={action}/>}
      {modal.type==='document'&&<DocumentForm kind={modal.value} data={data} busy={busy} action={action}/>}
      {modal.type==='detail'&&<DocumentDetail value={modal.value} data={data} admin={admin} open={open} busy={busy} action={action} refresh={refresh} setError={setError}/>}
      {modal.type==='shipment'&&<ShipmentForm invoice={modal.value} data={data} busy={busy} action={action}/>}
      {modal.type==='payment'&&<PaymentForm invoice={modal.value} data={data} busy={busy} action={action}/>}
      {modal.type==='receipt'&&<ReceiptForm invoice={modal.value} data={data} busy={busy} action={action}/>}
      {modal.type==='assignment'&&<AssignmentForm line={modal.value} data={data} busy={busy} action={action}/>}
      {modal.type==='apply'&&<ApplyForm line={modal.value} data={data} busy={busy} action={action}/>}
      {modal.type==='cancel'&&<CancelForm line={modal.value} busy={busy} action={action}/>}
    </Modal>}
  </div>;
}
function Brand(){return <div className="brand"><div className="brand-icon"><Leaf size={24}/></div><div><strong>sanat<span>pharma</span></strong><small>CONTROL DE IMPORTACIONES</small></div></div>;}
function Auth({session,passwordMode,onDone}){
  const [mode,setMode]=useState(passwordMode?'password':'login'),[email,setEmail]=useState(''),[password,setPassword]=useState(''),[repeat,setRepeat]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState(''),[info,setInfo]=useState('');
  useEffect(()=>{if(passwordMode)setMode('password');},[passwordMode]);
  async function submit(e){e.preventDefault();if(!configured)return;setBusy(true);setError('');setInfo('');try{
    if(mode==='password'){
      if(!session)throw new Error('Abre el enlace de invitación o recuperación de tu correo para establecer la contraseña.');
      if(password!==repeat)throw new Error('Las contraseñas no coinciden.');
      const {error}=await supabase.auth.updateUser({password});if(error)throw error;onDone();
    }else if(mode==='reset'){
      const {error}=await supabase.auth.resetPasswordForEmail(email.trim(),{redirectTo:location.origin+'/?acceso=1'});if(error)throw error;setInfo('Si el correo tiene una cuenta, recibirás un enlace para recuperar tu acceso.');
    }else{const {error}=await supabase.auth.signInWithPassword({email:email.trim(),password});if(error)throw error;}
  }catch(e){setError(errorMessage(e));}finally{setBusy(false);}}
  return <div className="auth-shell"><section className="auth-story"><Brand/><div><span className="eyebrow">CLARIDAD EN CADA ETAPA</span><h1>Tu pedido.<br/>Su recorrido.<br/><em>Todo bajo control.</em></h1><p>Una visión compartida de las proformas,<br/>las facturas y lo que está por llegar.</p><div className="route-illustration"><span><Files/>Proforma</span><i/><span><Ship/>En camino</span><i/><span><Package/>Recibido</span></div></div><small>Sanat Pharma · Control de importaciones</small></section><section className="auth-form"><div className="auth-card"><div className="auth-lock"><LockKeyhole size={23}/></div><div className="eyebrow">TU ESPACIO DE TRABAJO</div><h2>{mode==='password'?'Define tu contraseña':mode==='reset'?'Recupera tu acceso':'Qué bueno tenerte aquí.'}</h2><p>{mode==='login'?'Ingresa con tu cuenta del equipo.':mode==='reset'?'Te enviaremos un enlace a tu correo.':'Utiliza al menos 12 caracteres para proteger tu cuenta.'}</p>{!configured&&<div role="alert" className="message error">Falta conectar la configuración pública de Supabase.</div>}{error&&<div className="message error" role="alert">{error}</div>}{info&&<div className="message success" role="status">{info}</div>}<form onSubmit={submit}>{mode!=='password'&&<Field label="Correo electrónico"><input type="email" autoComplete="username" required value={email} onChange={e=>setEmail(e.target.value)} placeholder="tu.correo@sanatpharma.com"/></Field>}{mode!=='reset'&&<Field label={mode==='password'?'Nueva contraseña':'Contraseña'}><input type="password" autoComplete={mode==='password'?'new-password':'current-password'} required minLength={mode==='password'?12:undefined} value={password} onChange={e=>setPassword(e.target.value)} placeholder="Tu contraseña"/></Field>}{mode==='password'&&<Field label="Repite la contraseña"><input type="password" required autoComplete="new-password" minLength={12} value={repeat} onChange={e=>setRepeat(e.target.value)}/></Field>}<Button disabled={busy||!configured} icon={ArrowRight}>{busy?'Un momento…':mode==='login'?'Entrar al control':mode==='reset'?'Enviar enlace':'Guardar contraseña'}</Button></form>{mode!=='password'&&<button className="text-button" onClick={()=>{setMode(mode==='login'?'reset':'login');setError('');setInfo('');}}>{mode==='login'?'Olvidé mi contraseña':'Volver al inicio de sesión'}</button>}{mode==='password'&&<button className="text-button" onClick={async()=>{if(supabase)await supabase.auth.signOut();onDone();setMode('login');}}>Volver al acceso</button>}<div className="auth-note"><LockKeyhole size={14}/> Acceso exclusivo para el equipo autorizado.</div></div></section></div>;
}
function SearchBox({value,onChange,placeholder='Buscar producto o código…'}){return <div className="search"><Search size={17}/><input aria-label="Buscar" placeholder={placeholder} value={value} onChange={e=>onChange(e.target.value)}/></div>;}
function Forecast({data,query,setQuery}){
  const [scope,setScope]=useState('all'),[document,setDocument]=useState(''),[metric,setMetric]=useState('facturado');
  const source=scope==='proforma'?data.v_forecast_proforma:scope==='factura'?data.v_forecast_factura:data.v_forecast_producto;
  const filtered=source.filter(r=>(!document||r[scope+'_id']===document)&&`${r.codigo} ${r.nombre}`.toLowerCase().includes(query.toLowerCase()));
  const docs=scope==='proforma'?data.proformas:scope==='factura'?data.facturas:[];
  const pending=data.v_forecast_factura.filter(r=>Number(r.pendiente_recepcion)>0);
  const alerts=data.v_forecast_producto.filter(r=>Number(r.sin_asignar)>0||Number(r.exceso_facturado)>0||Number(r.recibido_sin_aplicar)>0||Number(r.exceso_recibido)>0);
  const metrics=[['Proformas registradas',data.proformas.length,Files,'El origen de cada pedido'],['Facturas en seguimiento',new Set(pending.map(r=>r.factura_id)).size,Ship,'Con productos pendientes de recepción'],['Productos con pendientes',new Set(data.v_forecast_producto.filter(r=>+r.pendiente_facturar>0||+r.pendiente_recepcion>0).map(r=>r.producto_id)).size,Package,'Por facturar o por recibir'],['Por conciliar',alerts.length,AlertCircle,'Diferencias que necesitan revisión']];
  const columns=scope==='proforma'?[['pedido_vigente','Pedido vigente'],['facturado','Facturado'],['recibido','Recibido'],['pendiente_facturar','Por facturar'],['facturado_pendiente_recepcion','Por recibir']]:scope==='factura'?[['facturado','Facturado'],['recibido','Recibido'],['pendiente_recepcion','Por recibir'],['sin_asignar','Sin asignar']]:[['pedido_vigente','Pedido vigente'],['facturado','Facturado'],['recibido','Recibido'],['pendiente_facturar','Por facturar'],['pendiente_recepcion','Por recibir']];
  return <><div className="metrics">{metrics.map(([label,value,Icon,hint],i)=><div className={'metric metric-'+i} key={label}><div className="metric-top"><span>{label}</span><Icon size={19}/></div><strong>{number(value)}</strong><small>{hint}</small></div>)}</div><div className="panel forecast-panel"><div className="panel-title"><div><h2>Forecast por producto <span className="count">{filtered.length}</span></h2><p>Abre el detalle de cada producto para seguir sus documentos.</p></div><Button secondary icon={Download} disabled={!filtered.length} onClick={()=>downloadCSV('forecast.csv',filtered)}>Exportar</Button></div><div className="filterbar"><div className="segments">{[['all','Vista general'],['proforma','Por proforma'],['factura','Por factura']].map(([v,l])=><button className={scope===v?'selected':''} key={v} onClick={()=>{setScope(v);setDocument('');}}>{l}</button>)}</div><SearchBox value={query} onChange={setQuery}/>{scope!=='all'&&<select aria-label="Filtrar documento" value={document} onChange={e=>setDocument(e.target.value)}><option value="">Todos los documentos</option>{docs.map(d=><option key={d.id} value={d.id}>{d.numero}</option>)}</select>}</div>
    {filtered.length?<div className="table-scroll"><table className="forecast-table"><thead><tr><th>Producto / presentación</th>{scope!=='all'&&<th>Documento</th>}<th>Unidad</th>{columns.map(([k,l])=><th className="num" key={k}>{l}</th>)}<th>Control</th></tr></thead><tbody>{filtered.map((r,i)=><ForecastRow key={`${r.producto_id}-${r.unidad}-${i}`} r={r} scope={scope} columns={columns} data={data}/>)}</tbody></table></div>:<Empty title={query||document?'No encontramos coincidencias':'El control empieza con tu primer producto'} text={query||document?'Prueba otro código o cambia los filtros.':'Registra los productos y las proformas para empezar a ver su avance.'}/>}
    <div className="table-note"><span><i className="legend-dot"/> Por recibir corresponde a mercadería ya facturada.</span><span>Las cantidades se muestran en su unidad comercial.</span></div></div>
    {scope==='all'&&filtered.length>0&&<div className="panel matrix"><div className="panel-title"><div><h2>Documentos, lado a lado</h2><p>La vista de tu Excel: productos en filas y cada documento en columnas.</p></div><select aria-label="Medida de la matriz" value={metric} onChange={e=>setMetric(e.target.value)}><option value="facturado">Facturado</option><option value="recibido">Recibido</option></select></div><div className="table-scroll"><table><thead><tr><th>Producto / unidad</th>{data.proformas.map(p=><th key={p.id}>PROFORMA<small>{p.numero}</small></th>)}{data.facturas.map(f=><th key={f.id}>FACTURA<small>{f.numero}</small></th>)}</tr></thead><tbody>{filtered.map((r,i)=><tr key={i}><td>{r.nombre}<small>{r.codigo} · {r.unidad||'Sin movimientos'}</small></td>{data.proformas.map(p=><td className="num" key={p.id}>{number(sum(data.v_forecast_proforma.filter(l=>l.producto_id===r.producto_id&&l.unidad===r.unidad&&l.proforma_id===p.id),metric))}</td>)}{data.facturas.map(f=><td className="num" key={f.id}>{number(sum(data.v_forecast_factura.filter(l=>l.producto_id===r.producto_id&&l.unidad===r.unidad&&l.factura_id===f.id),metric))}</td>)}</tr>)}</tbody></table></div></div>}
    <div className="bottom-grid"><div className="panel"><div className="panel-title"><h2>Próximas llegadas</h2><Anchor size={20}/></div>{pending.length?pending.slice(0,4).map((r,i)=><div className="arrival" key={i}><div className="arrival-icon"><Ship size={19}/></div><div><strong>{r.factura}</strong><small>{r.nombre} · {number(r.pendiente_recepcion)} {r.unidad}</small></div><div className="arrival-date"><strong>{date(r.cochabamba_estimada)}</strong><small>Estimada · Cochabamba</small></div></div>):<p className="soft-empty">No hay llegadas pendientes registradas.</p>}</div><div className="insight"><span className="eyebrow">UNA COSA A LA VEZ</span><h2>Lo estimado orienta.<br/>Lo recibido confirma.</h2><p>Una fecha de llegada no cierra el pedido. La recepción real es la que actualiza tu control.</p><div className="insight-symbol"><Package size={47} strokeWidth={1}/><Check size={23}/></div></div></div>
  </>;
}
function relatedForecast(r,scope,data){
  let p=data.v_forecast_proforma.filter(l=>l.producto_id===r.producto_id&&l.unidad===r.unidad);
  let f=data.v_forecast_factura.filter(l=>l.producto_id===r.producto_id&&l.unidad===r.unidad);
  if(scope==='proforma'){
    p=p.filter(l=>l.detalle_proforma_id===r.detalle_proforma_id);
    f=data.v_asignaciones.filter(a=>a.detalle_proforma_id===r.detalle_proforma_id).map(a=>({
      ...data.v_forecast_factura.find(l=>l.detalle_factura_id===a.detalle_factura_id),facturado:a.facturado,recibido:a.recibido
    }));
  }else if(scope==='factura'){
    f=f.filter(l=>l.detalle_factura_id===r.detalle_factura_id);
    p=data.v_asignaciones.filter(a=>a.detalle_factura_id===r.detalle_factura_id).map(a=>({
      ...data.v_forecast_proforma.find(l=>l.detalle_proforma_id===a.detalle_proforma_id),facturado:a.facturado,recibido:a.recibido
    }));
  }
  return {p,f};
}
function ForecastRow({r,scope,columns,data}){
  const [expanded,setExpanded]=useState(false);
  const differences=+r.sin_asignar>0||+r.exceso_facturado>0||+r.recibido_sin_aplicar>0||+r.exceso_recibido>0;
  return <><tr><td><button className="product-link" onClick={()=>setExpanded(!expanded)} aria-expanded={expanded}><span className="product-box"><Package size={17}/></span><span><strong>{r.nombre}</strong><small>{r.codigo} {r.presentacion?'· '+r.presentacion:''}</small></span><ChevronRight size={15} className={expanded?'rotate':''}/></button></td>{scope!=='all'&&<td>{r.proforma||r.factura}</td>}<td className="muted">{r.unidad||'—'}</td>{columns.map(([k])=><td className={'num '+(k.includes('pendiente')&&+r[k]>0?'pending':'')} key={k}>{number(r[k])}</td>)}<td><Badge tone={differences?'amber':'green'}>{differences?'Revisar':+r.pendiente_facturar>0||+r.pendiente_recepcion>0||+r.facturado_pendiente_recepcion>0?'En seguimiento':'Sin pendientes'}</Badge></td></tr>{expanded&&<tr className="expanded"><td colSpan={columns.length+(scope==='all'?3:4)}><div className="expanded-grid"><div><h4>Proformas del producto</h4>{relatedForecast(r,scope,data).p.map((l,i)=><p key={i}><strong>{l.proforma}</strong> · {number(l.facturado)} facturadas · {number(l.recibido)} recibidas</p>)}</div><div><h4>Facturas y fechas estimadas</h4>{relatedForecast(r,scope,data).f.map((l,i)=><p key={i}><strong>{l.factura}</strong> · {number(l.facturado)} {l.unidad} · {date(l.cochabamba_estimada)}</p>)}{differences&&<p className="pending">Sin asignar: {number(r.sin_asignar)} · Facturado en exceso: {number(r.exceso_facturado)} · Recibido sin aplicar: {number(r.recibido_sin_aplicar)} · Recibido en exceso: {number(r.exceso_recibido)}</p>}</div></div></td></tr>}</>;
}
function Products({data,admin,query,setQuery,open}){
  const rows=data.productos.filter(p=>`${p.codigo} ${p.nombre}`.toLowerCase().includes(query.toLowerCase()));
  return <div className="panel"><div className="panel-title"><div><h2>Tu catálogo <span className="count">{rows.length}</span></h2><p>Datos principales y referencias del proveedor.</p></div>{admin&&<Button icon={Plus} onClick={()=>open('product')}>Nuevo producto</Button>}</div><div className="filterbar"><SearchBox value={query} onChange={setQuery}/></div>{rows.length?<div className="table-scroll"><table><thead><tr><th>Código</th><th>Producto</th><th>Presentación</th><th>Packing de referencia</th><th>Estado</th>{admin&&<th/>}</tr></thead><tbody>{rows.map(p=><tr key={p.id}><td className="code">{p.codigo}</td><td><strong>{p.nombre}</strong></td><td>{p.presentacion||'—'}</td><td>{byId(data.productos_complemento,p.id)?.packing_referencia||'—'}</td><td><Badge>{p.estado}</Badge></td>{admin&&<td><button className="text-button" onClick={()=>open('product',p)}>Editar</button></td>}</tr>)}</tbody></table></div>:<Empty title={query?'No hay coincidencias':'Tu catálogo está listo para empezar'} text="Añade los productos que vas a utilizar en tus documentos."/>}</div>;
}
function Documents({kind,data,admin,open}){
  const [q,setQ]=useState('');const invoice=kind==='factura';const rows=(invoice?data.facturas:data.proformas).filter(r=>`${r.numero} ${r.proveedor}`.toLowerCase().includes(q.toLowerCase()));
  return <div className="panel"><div className="panel-title"><div><h2>{invoice?'Facturas del proveedor':'Pedidos aprobados'} <span className="count">{rows.length}</span></h2><p>{invoice?'Se registran cuando el proveedor las emite.':'Cada proforma conserva su cantidad y precio originales.'}</p></div>{admin&&<Button icon={Plus} disabled={!data.productos.length} onClick={()=>open('document',kind)}>Nueva {kind}</Button>}</div>{!data.productos.length&&admin&&<p className="inline-note">Primero registra los productos en el catálogo.</p>}<div className="filterbar"><SearchBox value={q} onChange={setQ} placeholder="Buscar documento o proveedor…"/></div>{rows.length?<div className="table-scroll"><table><thead><tr><th>Documento</th><th>Proveedor</th><th>Fecha de emisión</th><th>Productos</th><th>Importe</th><th/></tr></thead><tbody>{rows.map(r=>{const lines=(invoice?data.detalles_factura:data.detalles_proforma).filter(l=>l[invoice?'factura_id':'proforma_id']===r.id);return <tr key={r.id}><td><span className="doc-icon"><FileText size={17}/></span><strong>{r.numero}</strong></td><td>{r.proveedor}</td><td>{date(r[invoice?'fecha_emision':'fecha_documento'])}</td><td>{lines.length} líneas</td><td>{money(invoice?r.importe_documento:lines.reduce((t,l)=>t+Number(l.cantidad_pedida)*Number(l.precio_unitario),0),r.moneda)}</td><td><button className="text-button" onClick={()=>open('detail',{kind,doc:r})}>Ver detalle <ArrowUpRight size={14}/></button></td></tr>;})}</tbody></table></div>:<Empty title={`Aún no hay ${invoice?'facturas':'proformas'}`} text="Registra el documento y sus productos para empezar el seguimiento."/>}</div>;
}
function Tracking({data,admin,open}){
  return <div className="panel"><div className="panel-title"><div><h2>De origen a Cochabamba</h2><p>Una factura, un BL. Las recepciones se registran por cantidad.</p></div><Badge>{data.facturas.length} facturas</Badge></div>{data.facturas.length?data.facturas.map(f=>{const e=data.embarques.find(e=>e.factura_id===f.id)||{};const lines=data.v_forecast_factura.filter(l=>l.factura_id===f.id);return <div className="shipment" key={f.id}><div className="shipment-top"><div><strong>{f.numero}</strong><span>{e.numero_bl||'BL por confirmar'}</span></div><div>{admin&&<><Button secondary onClick={()=>open('shipment',f)}>Editar fechas</Button><Button disabled={!e.id} onClick={()=>open('receipt',f)} icon={Plus}>Registrar recepción</Button></>}</div></div><div className="milestones">{[['Salida',e.salida_estimada,e.salida_real],['Arica',e.arica_estimada,e.arica_real],['Cochabamba',e.cochabamba_estimada,e.cochabamba_real]].map(([l,est,real])=><div key={l} className={real?'done':''}><span className="milestone-dot">{real?<Check size={13}/>:<span/>}</span><strong>{l}</strong><p>{real?date(real):date(est)}</p><small>{real?'Fecha real':est?'Fecha estimada':'Por confirmar'}</small></div>)}</div><div className="shipment-bottom"><span>{lines.filter(l=>+l.pendiente_recepcion>0).length} líneas por recibir</span><span>Una fecha real de arribo no reemplaza la recepción de productos.</span></div></div>;}):<Empty title="Los embarques aparecerán aquí" text="Registra una factura y añade su BL y sus fechas de transporte."/>}</div>;
}
function Payments({data,admin,open}){return <div className="panel"><div className="panel-title"><div><h2>Anticipos y saldos</h2><p>El 30 % se calcula sobre la factura; solo los pagos registrados reducen el saldo.</p></div></div>{data.v_control_pagos.length?<div className="table-scroll"><table><thead><tr><th>Factura</th><th>Importe</th><th>Anticipo 30 %</th><th>Pagado</th><th>Saldo</th><th>Plazo</th>{admin&&<th/>}</tr></thead><tbody>{data.v_control_pagos.map(p=><tr key={p.factura_id}><td><strong>{p.numero}</strong></td><td>{money(p.importe_documento,p.moneda)}</td><td>{money(p.anticipo_requerido,p.moneda)}</td><td>{money(p.pagado,p.moneda)}</td><td className="pending">{money(p.saldo,p.moneda)}</td><td><Badge tone={p.estado_financiero==='VENCIDO'?'amber':''}>{p.estado_financiero}</Badge></td>{admin&&<td><button className="text-button" onClick={()=>open('payment',byId(data.facturas,p.factura_id))}>Registrar pago <Plus size={14}/></button></td>}</tr>)}</tbody></table></div>:<Empty title="Los pagos empiezan con una factura" text="Aquí verás el anticipo requerido y el saldo de cada documento."/>}</div>;}

function modalTitle(m){return {product:m.value?'Editar producto':'Nuevo producto',document:`Nueva ${m.value}`,detail:m.value?.doc?.numero,shipment:'BL y fechas del embarque',payment:'Registrar pago',receipt:'Registrar recepción real',assignment:'Asignar a una proforma',apply:'Aplicar recepción a proforma',cancel:'Cancelar cantidad del pedido'}[m.type];}
function FormFooter({busy,label='Guardar registro'}){return <div className="form-footer"><span>Los cambios quedan en el historial.</span><Button disabled={busy||exampleMode} icon={Check}>{busy?'Guardando…':label}</Button></div>;}
function ProductForm({value,data,busy,action}){
  const c=byId(data.productos_complemento,value?.id)||{};const [form,setForm]=useState({codigo:'',nombre:'',estado:'ACTIVO',presentacion:'',...value,nombre_proveedor:c.nombre_proveedor||'',proveedor:c.proveedor||'',packing_referencia:c.packing_referencia||'',unidades_por_caja:c.unidades_por_caja||''});
  const input=(key,label,extra={})=><Field label={label}><input value={form[key]??''} onChange={e=>setForm({...form,[key]:e.target.value})} {...extra}/></Field>;
  return <form onSubmit={e=>{e.preventDefault();action(()=>rpc('guardar_producto',{datos:{id:value?.id,codigo:form.codigo,nombre:form.nombre,estado:form.estado,presentacion:form.presentacion,observaciones:form.observaciones},complemento:{nombre_proveedor:form.nombre_proveedor,proveedor:form.proveedor,packing_referencia:form.packing_referencia,unidades_por_caja:form.unidades_por_caja}}));}}><div className="form-grid">{input('codigo','Código',{required:true})}{input('nombre','Nombre del producto',{required:true})}{input('presentacion','Presentación')}{input('estado','Estado',{required:true})}</div><h3>Referencia del proveedor</h3><div className="form-grid">{input('nombre_proveedor','Nombre en documentos')}{input('proveedor','Proveedor')}{input('packing_referencia','Packing de referencia')}{input('unidades_por_caja','Unidades por caja',{type:'number',min:0,step:'0.0001'})}</div><FormFooter busy={busy}/></form>;
}
function DocumentForm({kind,data,busy,action}){
  const invoice=kind==='factura';const [head,setHead]=useState({id:crypto.randomUUID(),proveedor:'',numero:'',fecha_documento:today(),fecha_emision:today(),moneda:'USD',importe_documento:'',vencimiento_saldo:'',observaciones:''});const [lines,setLines]=useState([blankLine()]);
  const change=(k,v)=>setHead({...head,[k]:v});const lineChange=(key,k,v)=>setLines(lines.map(l=>l.key===key?{...l,[k]:v}:l));
  const total=lines.reduce((n,l)=>n+Number(l.cantidad||0)*Number(l.precio_unitario||0),0);
  return <form onSubmit={e=>{e.preventDefault();action(()=>rpc('crear_documento',{tipo:kind,cabecera:head,lineas:lines.map(({key,...l})=>l)}),'Documento y productos guardados');}}><div className="form-grid three"><Field label="Número de documento"><input required value={head.numero} onChange={e=>change('numero',e.target.value)}/></Field><Field label="Proveedor"><input required value={head.proveedor} list="proveedores" onChange={e=>change('proveedor',e.target.value)}/><datalist id="proveedores">{[...new Set([...data.proformas,...data.facturas].map(d=>d.proveedor))].map(p=><option key={p}>{p}</option>)}</datalist></Field><Field label="Fecha de emisión"><input required type="date" value={head[invoice?'fecha_emision':'fecha_documento']} onChange={e=>change(invoice?'fecha_emision':'fecha_documento',e.target.value)}/></Field><Field label="Moneda"><select value={head.moneda} onChange={e=>change('moneda',e.target.value)}>{['USD','BOB','EUR','INR'].map(c=><option key={c}>{c}</option>)}</select></Field>{invoice&&<><Field label="Importe completo de la factura"><input required type="number" min="0" step="0.0001" value={head.importe_documento} onChange={e=>change('importe_documento',e.target.value)}/></Field><Field label="Vencimiento del saldo" hint="Déjalo vacío si no está confirmado."><input type="date" value={head.vencimiento_saldo} onChange={e=>change('vencimiento_saldo',e.target.value)}/></Field></>}</div><div className="section-title"><h3>Productos del documento</h3><Button type="button" secondary icon={Plus} onClick={()=>setLines([...lines,blankLine()])}>Añadir línea</Button></div><div className="document-lines">{lines.map((l,i)=><div className="document-line" key={l.key}><div className="line-number">{String(i+1).padStart(2,'0')}</div><div className="line-fields"><div className="form-grid three"><Field label="Producto"><select required value={l.producto_id} onChange={e=>{const p=byId(data.productos,e.target.value);lineChange(l.key,'producto_id',p?.id||'');}}><option value="">Seleccionar producto</option>{data.productos.map(p=><option key={p.id} value={p.id}>{p.codigo} · {p.nombre}</option>)}</select></Field><Field label="Cantidad"><input required type="number" min="0.0001" step="0.0001" value={l.cantidad} onChange={e=>lineChange(l.key,'cantidad',e.target.value)}/></Field><Field label="Unidad comercial"><input required value={l.unidad} onChange={e=>lineChange(l.key,'unidad',e.target.value)}/></Field><Field label="Packing del documento"><input value={l.packing} onChange={e=>lineChange(l.key,'packing',e.target.value)}/></Field><Field label="Precio unitario"><input required type="number" min="0" step="0.0001" value={l.precio_unitario} onChange={e=>lineChange(l.key,'precio_unitario',e.target.value)}/></Field>{invoice&&<Field label="Proforma escrita por el proveedor"><input value={l.referencia_proforma_documento} onChange={e=>lineChange(l.key,'referencia_proforma_documento',e.target.value)} placeholder="Referencia del PDF"/></Field>}</div>{invoice&&<p className="footnote">Puedes conciliar esta línea con una o varias proformas después de guardarla.</p>}</div><button type="button" className="icon-button" disabled={lines.length===1} aria-label={`Quitar línea ${i+1}`} onClick={()=>setLines(lines.filter(x=>x.key!==l.key))}><Trash2 size={17}/></button></div>)}</div><div className="document-total"><span>Total de las líneas</span><strong>{money(total,head.moneda)}</strong></div>{invoice&&head.importe_documento!==''&&Math.abs(+head.importe_documento-total)>0.005&&<p className="inline-note">El importe de la factura difiere del total de las líneas. Se conservará la diferencia para revisarla.</p>}<Field label="Observaciones"><textarea rows={2} value={head.observaciones} onChange={e=>change('observaciones',e.target.value)}/></Field><FormFooter busy={busy} label={`Guardar ${kind}`}/></form>;
}
function DocumentDetail({value,data,admin,open,busy,action,refresh,setError}){
  const {kind,doc}=value,invoice=kind==='factura';const lines=(invoice?data.detalles_factura:data.detalles_proforma).filter(l=>l[invoice?'factura_id':'proforma_id']===doc.id);const attachments=data.adjuntos.filter(a=>a[invoice?'factura_id':'proforma_id']===doc.id);const [uploading,setUploading]=useState(false),[links,setLinks]=useState({});
  async function upload(file){if(!file||exampleMode)return;if(file.type!=='application/pdf'||file.size>10485760){setError('Selecciona un PDF de hasta 10 MB.');return;}setUploading(true);try{const id=crypto.randomUUID(),name=file.name.replace(/[^a-zA-Z0-9._-]/g,'_'),ruta=`${id}/${name}`;await save('adjuntos',{id,[invoice?'factura_id':'proforma_id']:doc.id,nombre:file.name,ruta});const {error}=await supabase.storage.from('documentos-control').upload(ruta,file,{contentType:'application/pdf',upsert:false});if(error)throw error;await refresh();}catch(e){setError('El documento se conserva. No se pudo completar la subida del PDF: '+errorMessage(e));await refresh();}finally{setUploading(false);}}
  async function retry(a,file){if(!file||exampleMode)return;if(file.type!=='application/pdf'||file.size>10485760){setError('Selecciona un PDF de hasta 10 MB.');return;}setUploading(true);try{const {error}=await supabase.storage.from('documentos-control').upload(a.ruta,file,{contentType:'application/pdf',upsert:false});if(error)throw error;setError('');}catch(e){setError(errorMessage(e));}finally{setUploading(false);}}
  async function view(a){if(exampleMode)return;const {data:r,error}=await supabase.storage.from('documentos-control').createSignedUrl(a.ruta,60);if(error){setError('El PDF no está disponible. Si la carga quedó pendiente, vuelve a subirlo.');return;}setLinks({...links,[a.id]:r.signedUrl});}
  return <><div className="detail-meta"><span>{doc.proveedor}</span><span>{date(doc[invoice?'fecha_emision':'fecha_documento'])}</span><Badge>{doc.moneda}</Badge></div>{invoice&&admin&&<div className="detail-actions"><Button secondary onClick={()=>open('shipment',doc)}>BL y fechas</Button><Button secondary onClick={()=>open('payment',doc)}>Registrar pago</Button></div>}<div className="table-scroll"><table><thead><tr><th>Producto</th><th>Cantidad</th><th>Packing</th><th>Precio</th>{admin&&<th/>}</tr></thead><tbody>{lines.map(l=>{const p=byId(data.productos,l.producto_id);return <tr key={l.id}><td><strong>{p?.nombre}</strong><small>{p?.codigo}{invoice&&l.referencia_proforma_documento?' · '+l.referencia_proforma_documento:''}</small></td><td>{number(l[invoice?'cantidad':'cantidad_pedida'])} {l.unidad}</td><td>{l.packing||'—'}</td><td>{money(l.precio_unitario,doc.moneda)}</td>{admin&&<td><button className="text-button" onClick={()=>open(invoice?'assignment':'cancel',l)}>{invoice?'Conciliar':'Cancelar cantidad'}</button></td>}</tr>;})}</tbody></table></div>{invoice&&<><h3>Conciliación con proformas</h3>{data.v_asignaciones.filter(a=>a.factura_id===doc.id).map(a=><div className="reconcile-row" key={a.id}><strong>{byId(data.proformas,a.proforma_id)?.numero}</strong><span>{number(a.facturado)} facturadas · {number(a.recibido)} recibidas</span>{(a.diferencia_precio||a.diferencia_packing)&&<Badge tone="amber">{a.diferencia_precio?'Precio diferente':'Packing diferente'}</Badge>}</div>)}{data.v_forecast_factura.filter(l=>l.factura_id===doc.id&&+l.sin_asignar>0).map(l=><p className="inline-note" key={l.detalle_factura_id}>{l.nombre}: {number(l.sin_asignar)} {l.unidad} pendientes de asignar a una proforma.</p>)}<h3>Recepciones registradas</h3>{data.detalles_recepcion.filter(r=>lines.some(l=>l.id===r.detalle_factura_id)).map(r=><div className="reconcile-row" key={r.id}><span>{date(byId(data.recepciones,r.recepcion_id)?.fecha_real)} · {number(r.cantidad_recibida)} recibidas</span>{admin&&<button className="text-button" onClick={()=>open('apply',r)}>Aplicar a proforma</button>}</div>)}<h3>Pagos registrados</h3>{data.pagos.filter(p=>p.factura_id===doc.id).map(p=><div className="reconcile-row" key={p.id}><span>{date(p.fecha)} · {p.referencia}</span><strong>{money(p.importe,doc.moneda)}</strong></div>)}</>}{doc.observaciones&&<p>{doc.observaciones}</p>}<div className="section-title"><h3>Documentos PDF</h3>{admin&&<label className="button secondary upload-button"><Upload size={16}/>{uploading?'Subiendo…':'Adjuntar PDF'}<input type="file" accept="application/pdf" disabled={uploading||exampleMode} onChange={e=>upload(e.target.files[0])}/></label>}</div>{attachments.length?attachments.map(a=><div className="attachment" key={a.id}><FileText size={18}/><span>{a.nombre}</span>{links[a.id]?<a target="_blank" rel="noreferrer" href={links[a.id]}>Abrir PDF (1 minuto)</a>:<button className="text-button" onClick={()=>view(a)}>Preparar enlace</button>}{admin&&<label className="text-button upload-button">Reintentar carga<input type="file" accept="application/pdf" disabled={uploading||exampleMode} onChange={e=>retry(a,e.target.files[0])}/></label>}</div>):<p className="soft-empty">Todavía no hay archivos adjuntos.</p>}</>;
}
function ShipmentForm({invoice,data,busy,action}){
  const old=data.embarques.find(e=>e.factura_id===invoice.id),[form,setForm]=useState(old||{factura_id:invoice.id});const keys=[['fecha_bl','Fecha BL'],['salida_estimada','Salida estimada'],['salida_real','Salida real'],['arica_estimada','Arica estimada'],['arica_real','Arica real'],['cochabamba_estimada','Cochabamba estimada'],['cochabamba_real','Cochabamba real']];
  return <form onSubmit={e=>{e.preventDefault();const values={factura_id:invoice.id,numero_bl:form.numero_bl?.trim()||null,observaciones:form.observaciones||null};keys.forEach(([k])=>values[k]=form[k]||null);action(()=>save('embarques',values,old?.id),'Fechas del embarque actualizadas');}}><p>{invoice.numero} · {invoice.proveedor}</p><Field label="Número BL" hint="Puedes completar las estimaciones antes de conocer el BL."><input value={form.numero_bl||''} onChange={e=>setForm({...form,numero_bl:e.target.value})}/></Field><div className="form-grid">{keys.map(([k,l])=><Field label={l} key={k}><input type="date" value={form[k]||''} onChange={e=>setForm({...form,[k]:e.target.value})}/></Field>)}</div><Field label="Observaciones"><textarea value={form.observaciones||''} onChange={e=>setForm({...form,observaciones:e.target.value})}/></Field><FormFooter busy={busy}/></form>;
}
function PaymentForm({invoice,data,busy,action}){
  const [form,setForm]=useState({id:crypto.randomUUID(),factura_id:invoice.id,fecha:today(),importe:'',referencia:'',observaciones:''});const p=data.v_control_pagos.find(p=>p.factura_id===invoice.id);
  return <form onSubmit={e=>{e.preventDefault();action(()=>save('pagos',form),'Pago registrado');}}><div className="payment-summary"><span>{invoice.numero}</span><strong>Saldo: {money(p?.saldo,invoice.moneda)}</strong><small>Anticipo pendiente: {money(p?.anticipo_pendiente,invoice.moneda)}</small></div><div className="form-grid"><Field label="Fecha del pago"><input required type="date" value={form.fecha} onChange={e=>setForm({...form,fecha:e.target.value})}/></Field><Field label={`Importe pagado (${invoice.moneda})`}><input required type="number" min="0.0001" step="0.0001" value={form.importe} onChange={e=>setForm({...form,importe:e.target.value})}/></Field></div><Field label="Referencia o comprobante"><input required value={form.referencia} onChange={e=>setForm({...form,referencia:e.target.value})}/></Field><Field label="Observaciones"><textarea value={form.observaciones} onChange={e=>setForm({...form,observaciones:e.target.value})}/></Field><FormFooter busy={busy} label="Guardar pago"/></form>;
}
function ReceiptForm({invoice,data,busy,action}){
  const shipment=data.embarques.find(e=>e.factura_id===invoice.id);const [head,setHead]=useState({id:crypto.randomUUID(),embarque_id:shipment?.id,fecha_real:today(),almacen:'Cochabamba',documento:''}),[amounts,setAmounts]=useState({}),[validation,setValidation]=useState('');const lines=data.detalles_factura.filter(l=>l.factura_id===invoice.id);
  return <form onSubmit={e=>{e.preventDefault();const ls=lines.filter(l=>Number(amounts[l.id])>0).map(l=>({detalle_factura_id:l.id,cantidad_recibida:amounts[l.id]}));if(!ls.length){setValidation('Ingresa al menos una cantidad recibida.');return;}action(()=>rpc('registrar_recepcion',{cabecera:head,lineas:ls}),'Recepción física registrada. Puedes aplicarla a sus proformas desde la factura.');}}><p>{invoice.numero} · Las cantidades corresponden a lo recibido en esta entrega.</p>{validation&&<div role="alert" className="message error">{validation}</div>}<div className="form-grid three">{[['fecha_real','Fecha real','date'],['almacen','Almacén','text'],['documento','Documento de recepción','text']].map(([k,l,type])=><Field label={l} key={k}><input required type={type} value={head[k]} onChange={e=>setHead({...head,[k]:e.target.value})}/></Field>)}</div><div className="table-scroll"><table><thead><tr><th>Producto</th><th>Facturado</th><th>Recibido antes</th><th>Recibido ahora</th></tr></thead><tbody>{lines.map(l=>{const p=byId(data.productos,l.producto_id),v=data.v_forecast_factura.find(v=>v.detalle_factura_id===l.id);return <tr key={l.id}><td>{p?.nombre}<small>{p?.codigo} · {l.unidad}</small></td><td>{number(l.cantidad)}</td><td>{number(v?.recibido)}</td><td><input aria-label={`Recibido ahora ${p?.codigo}`} type="number" min="0" step="0.0001" value={amounts[l.id]||''} onChange={e=>setAmounts({...amounts,[l.id]:e.target.value})}/></td></tr>;})}</tbody></table></div><p className="footnote">Luego aplica las cantidades recibidas a las proformas correspondientes desde el detalle de la factura. Una recepción sin aplicar aparece como pendiente de conciliación.</p><FormFooter busy={busy} label="Guardar recepción"/></form>;
}
function AssignmentForm({line,data,busy,action}){
  const invoice=byId(data.facturas,line.factura_id),existing=data.asignaciones.filter(a=>a.detalle_factura_id===line.id);const [form,setForm]=useState({id:crypto.randomUUID(),detalle_factura_id:line.id,detalle_proforma_id:'',cantidad:''});const candidates=data.detalles_proforma.filter(p=>p.producto_id===line.producto_id&&p.unidad===line.unidad&&byId(data.proformas,p.proforma_id)?.proveedor===invoice.proveedor&&!existing.some(a=>a.detalle_proforma_id===p.id));
  return <form onSubmit={e=>{e.preventDefault();action(()=>save('asignaciones',form),'Cantidad vinculada a la proforma');}}><p>Referencia del proveedor: <strong>{line.referencia_proforma_documento||'No indicada'}</strong></p><p>Sin asignar: <strong>{number(+line.cantidad-sum(existing,'cantidad'))} {line.unidad}</strong></p>{existing.map(a=><p className="inline-note" key={a.id}>{byId(data.proformas,byId(data.detalles_proforma,a.detalle_proforma_id)?.proforma_id)?.numero}: {number(a.cantidad)} asignadas</p>)}<Field label="Proforma y línea del mismo producto"><select required value={form.detalle_proforma_id} onChange={e=>setForm({...form,detalle_proforma_id:e.target.value})}><option value="">Seleccionar proforma</option>{candidates.map(p=><option key={p.id} value={p.id}>{byId(data.proformas,p.proforma_id)?.numero} · línea {p.numero_linea} · {number(+p.cantidad_pedida-+p.cantidad_cancelada)} {p.unidad} pedidas</option>)}</select></Field><Field label={`Cantidad a asignar (${line.unidad})`}><input required type="number" min="0.0001" step="0.0001" max={+line.cantidad-sum(existing,'cantidad')} value={form.cantidad} onChange={e=>setForm({...form,cantidad:e.target.value})}/></Field>{!candidates.length&&<p className="inline-note">No hay más líneas compatibles. Revisa el producto, la unidad y el proveedor de las proformas registradas.</p>}<FormFooter busy={busy} label="Guardar asignación"/></form>;
}
function ApplyForm({line,data,busy,action}){
  const existing=data.aplicaciones_recepcion.filter(a=>a.detalle_recepcion_id===line.id),[form,setForm]=useState({id:crypto.randomUUID(),detalle_recepcion_id:line.id,asignacion_id:'',cantidad:''});const candidates=data.asignaciones.filter(a=>a.detalle_factura_id===line.detalle_factura_id&&!existing.some(r=>r.asignacion_id===a.id));
  return <form onSubmit={e=>{e.preventDefault();action(()=>save('aplicaciones_recepcion',form),'Recepción aplicada a la proforma');}}><p>Disponible de esta recepción: <strong>{number(+line.cantidad_recibida-sum(existing,'cantidad'))}</strong></p><Field label="Proforma a la que corresponde"><select required value={form.asignacion_id} onChange={e=>setForm({...form,asignacion_id:e.target.value})}><option value="">Seleccionar asignación</option>{candidates.map(a=><option key={a.id} value={a.id}>{byId(data.proformas,byId(data.detalles_proforma,a.detalle_proforma_id)?.proforma_id)?.numero} · {number(a.cantidad-sum(data.aplicaciones_recepcion.filter(r=>r.asignacion_id===a.id),'cantidad'))} pendientes</option>)}</select></Field><Field label="Cantidad de esta recepción"><input required type="number" min="0.0001" step="0.0001" max={Math.min(+line.cantidad_recibida-sum(existing,'cantidad'),+(byId(candidates,form.asignacion_id)?.cantidad||0)-sum(data.aplicaciones_recepcion.filter(r=>r.asignacion_id===form.asignacion_id),'cantidad'))} value={form.cantidad} onChange={e=>setForm({...form,cantidad:e.target.value})}/></Field><FormFooter busy={busy} label="Aplicar recepción"/></form>;
}
function CancelForm({line,busy,action}){
  const [form,setForm]=useState({cantidad_cancelada:line.cantidad_cancelada||'',fecha_cancelacion:line.fecha_cancelacion||today(),motivo_cancelacion:line.motivo_cancelacion||''});
  return <form onSubmit={e=>{e.preventDefault();action(()=>save('detalles_proforma',form,line.id),'Cancelación registrada');}}><p>Pedido original: {number(line.cantidad_pedida)} {line.unidad}. La cancelación no modifica la cantidad original.</p><Field label="Cantidad cancelada total"><input required type="number" min="0" max={line.cantidad_pedida} step="0.0001" value={form.cantidad_cancelada} onChange={e=>setForm({...form,cantidad_cancelada:e.target.value})}/></Field><Field label="Fecha de cancelación"><input type="date" required value={form.fecha_cancelacion} onChange={e=>setForm({...form,fecha_cancelacion:e.target.value})}/></Field><Field label="Motivo"><textarea required value={form.motivo_cancelacion} onChange={e=>setForm({...form,motivo_cancelacion:e.target.value})}/></Field><FormFooter busy={busy}/></form>;
}
createRoot(document.getElementById('root')).render(<App/>);
